460	# Records the real-app demo (see README.md in this folder). Needs: Xvfb, PulseAudio, ffmpeg, the Pawse
461	# backend running with GEMINI_API_KEY and GRADIUM_API_KEY, and the React app built (cd web && npm run build).
462	set -euo pipefail
463	HERE="$(cd "$(dirname "$0")" && pwd)"
464	cd "$HERE/.."
465	APP_URL="${APP_URL:-http://127.0.0.1:8765/app/?live=1}"
466	OWNER_WAV="${OWNER_WAV:-$HERE/owner-line.wav}"
467	NARRATION_WAV="${NARRATION_WAV-$HERE/narrator-intro.wav}"  # narrator over the opening; NARRATION_WAV= (empty) to skip
468	[ -f "$NARRATION_WAV" ] || NARRATION_WAV=""
469	MIMI_DIR="${MIMI_DIR:-/mnt/pawse-demo-out/mimi}"  # make-mimi-clip.py output; skipped when missing
470	OUT_DIR="${OUT_DIR:-/mnt/pawse-demo-out}"  # heavy media stays off the repo disk
471	mkdir -p "$OUT_DIR"
472	
473	# Audio: Chromium plays into the null sink "rec" (ffmpeg records its monitor); the owner's line is
474	# played into the null sink "mic", exposed to Chromium as the source "owner_mic".
475	pulseaudio --check 2>/dev/null || pulseaudio --start --exit-idle-time=-1
476	pactl list short sinks | grep -q '\brec\b' || pactl load-module module-null-sink sink_name=rec sink_properties=device.description=rec >/dev/null
477	pactl list short sinks | grep -q '\bmic\b' || pactl load-module module-null-sink sink_name=mic sink_properties=device.description=mic >/dev/null
478	pactl list short sources | grep -q owner_mic || pactl load-module module-remap-source master=mic.monitor source_name=owner_mic >/dev/null
479	pactl set-default-sink rec
480	pactl set-default-source owner_mic
481	
482	# The stage page and the opening clip, served together.
483	STAGE_DIR="$(mktemp -d)"
484	ln -s "$HERE/stage.html" "$STAGE_DIR/stage.html"
485	MIMI_ENV=()
486	if [ -f "$MIMI_DIR/mimi-16x9.mp4" ]; then
487	  ln -s "$MIMI_DIR/mimi-16x9.mp4" "$STAGE_DIR/mimi.mp4"
488	  MIMI_ENV=(MIMI_INTRO=1 MIMI_CAMERA="$MIMI_DIR/mimi-9x16.mp4" MIMI_STILL="$MIMI_DIR/mimi-still.jpg")
489	fi
490	python3 -m http.server 4180 --bind 127.0.0.1 --directory "$STAGE_DIR" >/dev/null 2>&1 &
491	STAGE_PID=$!
492	trap 'kill $STAGE_PID 2>/dev/null || true; rm -rf "$STAGE_DIR"' EXIT
493	sleep 1
494	
495	RAW="$OUT_DIR/pawse-demo-real.mkv"
496	STAGE_URL="http://127.0.0.1:4180/stage.html?app=$(python3 -c 'import sys,urllib.parse;print(urllib.parse.quote(sys.argv[1]))' "$APP_URL")" \
497	env "${MIMI_ENV[@]}" OWNER_WAV="$OWNER_WAV" NARRATION_WAV="$NARRATION_WAV" OUT="$RAW" \
498	  xvfb-run -a -s "-screen 0 1920x1080x24" node "$HERE/record-real.mjs"
499	
500	# Deliverable: silent waits shortened to fit 2:00, h264 + loudness-normalised AAC mp4. Capped at 4 GB RAM so a
501	# memory regression in the cut fails fast instead of freezing the machine.
502	CUT=(python3 "$HERE/make-cut.py" "$RAW" "$OUT_DIR/pawse-demo-real.mp4" "${TARGET_SECONDS:-120}")
503	if systemd-run --user --scope -q -p MemoryMax=4G true 2>/dev/null; then
504	  systemd-run --user --scope -q -p MemoryMax=4G "${CUT[@]}"
505	else
506	  "${CUT[@]}"
507	fi
