"""Cut the uncut real-app take down to the target length by shortening silent waits only.

make-cut.py <raw.mkv> <out.mp4> [target_seconds]

Every stretch where nothing is heard (Gemini or Gradium latency, the simulated replies shown as text)
is shortened to a short pause; speech is never cut or sped up. The pause length shrinks until the
video fits the target. The opening hook is kept whole so its caption can be read.

Video is cut with one streaming `select` (frames outside the kept spans are dropped as they pass), never
with one `trim` per segment into `concat`: that queues every later segment's raw frames in RAM (~90 MB/s
at 1080p30) and froze the VM. Cut points sit on the frame grid so audio and video cut at the same times.
"""
import json
import os
import re
import subprocess
import sys
import tempfile

raw, out = sys.argv[1], sys.argv[2]
target = float(sys.argv[3]) if len(sys.argv) > 3 else 120.0
PROTECT_HEAD = 6.0  # the hook caption

duration = float(subprocess.check_output(
    ["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", raw]).strip())
rate = subprocess.check_output(["ffprobe", "-v", "error", "-select_streams", "v:0", "-show_entries",
                                "stream=r_frame_rate", "-of", "csv=p=0", raw], text=True).strip()
num, den = (rate.split("/") + ["1"])[:2]
fps = float(num) / float(den)
log = subprocess.run(["ffmpeg", "-i", raw, "-af", "silencedetect=noise=-45dB:d=1.5", "-vn", "-f", "null", "-"],
                     capture_output=True, text=True).stderr
starts = [float(x) for x in re.findall(r"silence_start: ([\d.]+)", log)]
ends = [float(x) for x in re.findall(r"silence_end: ([\d.]+)", log)]
silences = [(max(s, PROTECT_HEAD), e) for s, e in zip(starts, ends + [duration]) if e > PROTECT_HEAD]


def snap(t):
    return round(t * fps) / fps


def keeps(pause):
    """Segments to keep when each silence is shortened to `pause` seconds (half before, half after)."""
    segs, t = [], 0.0
    for s, e in silences:
        if e - s <= pause:
            continue
        segs.append((t, s + pause / 2))
        t = e - pause / 2
    segs.append((t, duration))
    return [(snap(a), snap(b)) for a, b in segs if snap(b) > snap(a)]


# Calls (marked by record-real.mjs in <raw>-marks.json) keep their opening seconds at normal speed, then play sped up
# with the German lowered under the subtitles, as the demo script asks. The speed is what fits the target, at most 4x.
CALL_HEAD, CALL_TAIL, MAX_SPEED, FAST_VOLUME = 6.0, 1.0, 4.0, 0.35
marks_path = re.sub(r"\.\w+$", "-marks.json", raw)
marks = json.load(open(marks_path)) if os.path.exists(marks_path) else []
starts_ = {m["call"]: m["t"] for m in marks if m.get("edge") == "start"}
fast = [(snap(starts_[m["call"]] + CALL_HEAD), snap(m["t"] - CALL_TAIL)) for m in marks
        if m.get("edge") == "end" and m["call"] in starts_ and m["t"] - CALL_TAIL > starts_[m["call"]] + CALL_HEAD]


def pieces(segs, speed):
    """Kept segments split at the fast ranges, as (start, end, speed)."""
    out = []
    for a, b in segs:
        cuts = sorted({a, b, *[x for f in fast for x in f if a < x < b]})
        for x, y in zip(cuts, cuts[1:]):
            inside = any(fa <= x and y <= fb for fa, fb in fast)
            out.append((x, y, speed if inside else 1.0))
    return out


def length(ps):
    return sum((b - a) / sp for a, b, sp in ps)


def fit(segs):
    normal = length(pieces(segs, 1.0)) - sum(b - a for a, b, sp in pieces(segs, 2.0) if sp > 1)
    quick = sum(b - a for a, b, sp in pieces(segs, 2.0) if sp > 1)
    if not quick:
        return 1.0
    return MAX_SPEED if target <= normal else min(MAX_SPEED, max(1.0, quick / (target - normal)))


pause = 3.0
while pause > 1.0 and length(pieces(keeps(pause), fit(keeps(pause)))) > target:
    pause -= 0.1
segs = keeps(pause)
speed = fit(segs)
ps = pieces(segs, speed)
total = length(ps)
print(f"raw {duration:.1f}s, {len(silences)} silences, pause {pause:.1f}s, {len(fast)} calls at {speed:.2f}x "
      f"-> {total:.1f}s in {len(ps)} pieces")

# Each kept frame keeps its own timestamp, mapped to the output clock (time cut before it removed, sped-up pieces
# compressed): x11grab drops frames under load, so renumbering frames would drift the picture ahead of the sound.
# -fps_mode cfr then fills dropped frames and drops surplus ones in the sped-up pieces.
# Half a frame of slack so a frame on a cut point lands in exactly one piece.
half, done, spans, maps, labels_on = 0.5 / fps, 0.0, [], [], []
for a, b, sp in ps:
    span = f"between({{}}\\,{a - half:.4f}\\,{b - half:.4f})"
    spans.append(span.format("t"))  # select calls the frame time t, setpts calls it T
    maps.append(f"{span.format('T')}*({done:.4f}+(T-{a:.4f})/{sp:.4f})")
    if sp > 1:
        labels_on.append(f"between(t\\,{done:.3f}\\,{done + (b - a) / sp:.3f})")
    done += (b - a) / sp
label = ""
if labels_on:
    font = "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"
    label = (f",drawtext=fontfile={font}:text='» call sped up ×{speed:.1f}, German audio lowered':fontsize=26:"
             f"fontcolor=white:box=1:boxcolor=black@0.55:boxborderw=12:x=w-tw-40:y=40:enable='{'+'.join(labels_on)}'")
parts, labels = [f"[0:v]select='{'+'.join(spans)}',setpts='({'+'.join(maps)})/TB'{label}[v];"], []
for i, (a, b, sp) in enumerate(ps):
    tempo = "".join(f",atempo={x:.4f}" for x in ([2.0, sp / 2] if sp > 2 else [sp])) if sp > 1 else ""
    vol = f",volume={FAST_VOLUME}" if sp > 1 else ""
    d = (b - a) / sp
    parts.append(f"[0:a]atrim={a:.4f}:{b:.4f},asetpts=PTS-STARTPTS{tempo}{vol},"
                 f"afade=t=in:d=0.03,afade=t=out:st={max(0, d - 0.03):.4f}:d=0.03[a{i}];")
    labels.append(f"[a{i}]")
graph = "".join(parts) + "".join(labels) + f"concat=n={len(ps)}:v=0:a=1[a0];[a0]loudnorm=I=-16:TP=-1.5:LRA=11[a]"

with tempfile.NamedTemporaryFile("w", suffix=".ffgraph", delete=False) as f:
    f.write(graph)
try:
    subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-i", raw, "-filter_complex_script", f.name,
                    "-map", "[v]", "-map", "[a]", "-fps_mode", "cfr", "-r", f"{fps:g}", "-c:v", "libx264", "-preset", "medium", "-crf", "20",
                    "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "160k", "-movflags", "+faststart", out], check=True)
finally:
    os.unlink(f.name)
// Records the 2-minute Mimi demo against the REAL Pawse app (/app/?live=1), not the mock.
// Gemini Live hears the owner through a virtual microphone and answers out loud; the care triage,
// the clinic search and the German draft are real backend calls; the vet and insurer calls are the
// app's own simulated rehearsal, with Pawse's German lines spoken by Gradium. The screen and the
// PulseAudio output are grabbed together by ffmpeg, so the sound in the video is what the app played.
// Run through record-real.sh, which sets up Xvfb, PulseAudio and the servers.
import { chromium } from '@playwright/test';
import { spawn } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';

const OUT = process.env.OUT || 'demo-out/pawse-demo-real.mkv';
const STAGE = process.env.STAGE_URL || 'http://127.0.0.1:4180/stage.html';
const OWNER_WAV = process.env.OWNER_WAV;
// Optional narrator over the opening (make-owner-line.py with another voice). Played into `rec` only, never `mic`,
// so Gemini Live does not hear it; the opening lasts until it has finished.
const NARRATION_WAV = process.env.NARRATION_WAV || '';
// Length of a PCM WAV from its header: data-chunk bytes / byte rate.
function wavSeconds(file) {
  const b = readFileSync(file);
  let byteRate = 0;
  for (let i = 12; i + 8 <= b.length;) {
    const id = b.toString('ascii', i, i + 4), size = b.readUInt32LE(i + 4);
    if (id === 'fmt ') byteRate = b.readUInt32LE(i + 16);
    if (id === 'data' && byteRate) return Math.min(size, b.length - i - 8) / byteRate;
    i += 8 + size + (size & 1);
  }
  throw new Error(`not a PCM WAV: ${file}`);
}
// Mimi footage (AI-generated, see make-mimi-clip.py): the stage opens on MIMI_INTRO, and the app's camera preview shows
// MIMI_CAMERA instead of a real camera; MIMI_STILL is sent to Gemini as the owner's photo.
const { MIMI_INTRO, MIMI_CAMERA, MIMI_STILL } = process.env;
const DISPLAY = process.env.DISPLAY;
const log = (...a) => console.log(`[${((Date.now() - t0) / 1000).toFixed(1)}s]`, ...a);
let t0 = Date.now();
const marks = [];

const browser = await chromium.launch({
  headless: false,
  args: ['--use-fake-ui-for-media-stream', '--autoplay-policy=no-user-gesture-required', '--window-position=0,0',
    '--window-size=1920,1080', '--disable-infobars', '--hide-scrollbars'],
});
const ctx = await browser.newContext({
  viewport: null,
  permissions: ['microphone', 'geolocation'],
  geolocation: { latitude: 47.3769, longitude: 8.5417 }, // Zurich, Kreis 1
});
// Camera stand-in: video requests get a stream of the Mimi clip, audio keeps the real (PulseAudio) microphone.
// The clip is served from the app's own origin so captureStream() is allowed.
if (MIMI_CAMERA) {
  await ctx.route('**/__mimi-camera.mp4', (route) => route.fulfill({ path: MIMI_CAMERA, contentType: 'video/mp4' }));
  await ctx.addInitScript(() => {
    if (!location.pathname.startsWith('/app')) return;
    const real = navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices);
    navigator.mediaDevices.getUserMedia = async (c = {}) => {
      if (!c.video) return real(c);
      const v = Object.assign(document.createElement('video'), { src: '/__mimi-camera.mp4', muted: true, playsInline: true });
      await v.play();
      const cam = v.captureStream();
      const tracks = cam.getVideoTracks();
      if (c.audio) tracks.push(...(await real({ audio: c.audio })).getAudioTracks());
      return new MediaStream(tracks);
    };
  });
}
const page = await ctx.newPage();
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') log('[console]', m.type(), m.text().slice(0, 160)); });
page.on('requestfinished', (r) => { if (r.url().includes('/api/')) log('[api]', r.method(), r.url().replace(/.*\/api/, '/api')); });
// Fullscreen through CDP (--kiosk / --start-fullscreen are ignored under Playwright), so no browser chrome is filmed.
const cdp = await ctx.newCDPSession(page);
const { windowId } = await cdp.send('Browser.getWindowForTarget');
await cdp.send('Browser.setWindowBounds', { windowId, bounds: { windowState: 'fullscreen' } });
await page.goto(STAGE);
const app = page.frameLocator('#app');
await app.locator('.start-btn').waitFor();
await page.waitForTimeout(1500);

// Start grabbing screen + system audio only once the page is painted.
const ff = spawn('ffmpeg', ['-y', '-loglevel', 'error', '-thread_queue_size', '1024', '-f', 'x11grab', '-framerate', '30',
  '-video_size', '1920x1080', '-draw_mouse', '0', '-i', `${DISPLAY}.0`, '-thread_queue_size', '1024', '-f', 'pulse', '-i', 'rec.monitor',
  '-c:v', 'libx264', '-preset', 'veryfast', '-crf', '18', '-pix_fmt', 'yuv420p', '-c:a', 'pcm_s16le', OUT], { stdio: ['pipe', 'inherit', 'inherit'] });
await page.waitForTimeout(800);
t0 = Date.now();

const stage = (caption, sub = '', badges = []) => { marks.push({ t: (Date.now() - t0) / 1000, caption }); return page.evaluate((a) => window.stage(a), { caption, sub, badges }); };
const hold = (ms) => page.waitForTimeout(ms);

// A visible cursor dot inside the phone; the real mouse drives it.
const CURSOR = `(() => { if (document.getElementById('dc')) return; const d = document.createElement('div'); d.id = 'dc';
  d.style.cssText = 'position:fixed;left:-50px;top:-50px;width:26px;height:26px;border-radius:50%;background:rgba(224,69,123,.8);box-shadow:0 0 0 5px rgba(224,69,123,.25);pointer-events:none;z-index:2147483647;transform:translate(-50%,-50%);transition:transform .08s';
  document.documentElement.appendChild(d);
  addEventListener('mousemove', e => { d.style.left = e.clientX + 'px'; d.style.top = e.clientY + 'px'; }, true);
  addEventListener('mousedown', () => d.style.transform = 'translate(-50%,-50%) scale(.7)', true);
  addEventListener('mouseup', () => d.style.transform = 'translate(-50%,-50%) scale(1)', true); })()`;
const frame = () => page.frames().find((f) => f.url().includes('/app/'));
let cur = { x: 1500, y: 600 };
async function glide(x, y, ms = 650) {
  await frame().evaluate(CURSOR).catch(() => {});
  const s = { ...cur }, n = Math.max(12, Math.round(ms / 16));
  const bend = (Math.random() - 0.5) * 80;
  for (let i = 1; i <= n; i++) {
    const t = i / n, e = t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2;
    const arc = Math.sin(Math.PI * t) * bend;
    await page.mouse.move(s.x + (x - s.x) * e + arc, s.y + (y - s.y) * e - arc / 2);
    await page.waitForTimeout(16);
  }
  cur = { x, y };
}
async function tap(locator, pause = 350) {
  await locator.scrollIntoViewIfNeeded();
  const b = await locator.boundingBox();
  await glide(b.x + b.width / 2, b.y + b.height / 2);
  await hold(pause);
  await page.mouse.down(); await hold(90); await page.mouse.up();
}
async function scrollPhone(dy, steps = 12) {
  await glide(1580, 700, 300);
  for (let i = 0; i < steps; i++) { await page.mouse.wheel(0, dy / steps); await hold(40); }
}
const say = (wav) => { for (const dev of ['mic', 'rec']) spawn('paplay', [`--device=${dev}`, wav]); };

try {
  // 1. Hook: Mimi on her three legs (AI-generated clip, labelled on screen)
  // The narrator sets the scene over the clip and the hook caption; the app starts only once it has finished, so
  // the Gemini Live greeting never talks over it.
  const narration = NARRATION_WAV ? wavSeconds(NARRATION_WAV) : 0;
  const narrationEnds = Date.now() + (narration + 0.5) * 1000;
  if (narration) { spawn('paplay', ['--device=rec', NARRATION_WAV]); log('narration', narration.toFixed(1) + 's'); }
  if (MIMI_INTRO) {
    await page.evaluate((a) => window.intro(a), { src: 'mimi.mp4', caption: 'Zurich. Mimi jumped off the wardrobe. Now she is limping.',
      seconds: 7.5, volume: narration ? 0.25 : 0.6 });
  }
  await stage('Your cat is hurt. You don’t speak German.', 'The owner just moved to Zurich.');
  await hold(Math.max(2500, narrationEnds - Date.now()));
  await stage('Talk to Pawse', 'A real Gemini Live voice session, no script.', [['live', 'Gemini Live']]);
  await tap(app.locator('.start-btn'));
  await tap(app.getByRole('button', { name: 'Agree and start' }), 600);
  await app.locator('text=/help/i').first().waitFor({ timeout: 30000 }); // Pawse's spoken greeting
  log('greeting');
  await hold(2500);

  // 2. The owner films Mimi and sends a photo, then speaks
  if (MIMI_CAMERA) {
    await stage('The owner shows Mimi', 'Camera preview stays on the phone. One photo goes to Gemini.', [['live', 'Gemini Live'], ['gen', 'Mimi footage']]);
    await tap(app.getByRole('button', { name: 'Camera', exact: true }));
    await app.locator('video').first().waitFor({ timeout: 10000 }).catch(() => {});
    await hold(3000); // the 8 s clip plays once: show it, send the photo, close the camera before it would repeat
    if (MIMI_STILL) { await app.locator('input[type=file]').setInputFiles(MIMI_STILL); log('photo sent'); }
    await hold(1500);
    await tap(app.getByRole('button', { name: 'Camera', exact: true })); // camera off
  }
  await tap(app.locator('button.ctl').first()); // unmute the mic
  await hold(600);
  say(OWNER_WAV);
  await stage('The owner explains, in English', 'Pawse hears the owner through the microphone and calls its care tool.', [['live', 'Gemini Live'], ['live', 'Gemini care triage']]);

  // 3. Triage
  await app.getByText("Pawse's advice").waitFor({ timeout: 90000 });
  log('triage');
  const level = (await app.locator('.sheet h2, .sheet strong, [class*=triage]').first().textContent().catch(() => '')) || '';
  log('triage level', level);
  await stage('A clear next step, not a diagnosis', 'Triage, questions to ask and what the vet will likely do.', [['live', 'Gemini care triage']]);
  await hold(5000);
  await scrollPhone(700);
  await hold(2000);

  // 4. Nearby clinic
  await stage('Find a clinic nearby', 'Real clinics around Zurich.', [['live', 'Gemini Maps clinic search']]);
  await tap(app.locator('.action-row button.btn.primary').first());
  const pick = app.getByRole('button', { name: /Prepare conversation/ }).first();
  await pick.waitFor({ timeout: 45000 });
  log('clinics');
  await hold(3500);
  await tap(pick);

  // 5. German draft for the vet, written live by Gemini
  await stage('Pawse writes the call in German', 'Gemini drafts the vet script with English subtitles. The owner reviews it first.', [['live', 'Gemini German draft']]);
  await hold(1000);
  await tap(app.getByText('Share these facts with Gemini', { exact: false }));
  await tap(app.getByRole('button', { name: 'Draft German script' }));
  await app.getByText('Review the German script').waitFor({ timeout: 65000 });
  log('draft');
  await hold(1500);
  await scrollPhone(500);
  await hold(3500);
  await tap(app.locator('details.handoff-more summary'));
  await tap(app.getByRole('button', { name: /simulated Mimi phone rehearsal/ }));

  // A call screen: listen in, opt in to Gradium's German voice, open the transcript, wait for the "next" button.
  const next = app.locator('[data-beat=next]');
  // Calls are marked so make-cut.py can play their middle sped up (the demo script's "speed up the calls").
  async function call(label) {
    marks.push({ t: (Date.now() - t0) / 1000, call: label, edge: 'start' });
    await app.locator('.pc-listen').waitFor({ timeout: 20000 });
    if (!(await app.locator('.pc-listen.on').count())) await tap(app.locator('.pc-listen'));
    const gradium = app.locator('.pc-gradium input');
    if (await gradium.isVisible().catch(() => false) && !(await gradium.isChecked())) await tap(gradium);
    await tap(app.locator('details.transcript summary')).catch(() => {});
    await next.waitFor({ timeout: 150000 });
    marks.push({ t: (Date.now() - t0) / 1000, call: label, edge: 'end' });
    log(label, 'done');
  }

  // 6. Vet call, with the owner's calendar
  await stage('Pawse calls the vet in German', 'Pawse’s German lines are spoken by Gradium. The vet’s replies are simulated text: nothing is dialled.', [['live', 'Gradium German voice'], ['sim', 'vet replies']]);
  const cal = app.locator('[data-beat=calendar]');
  cal.waitFor({ timeout: 120000 }).then(() => cal.scrollIntoViewIfNeeded()).then(() => stage('16:30 fits the owner’s calendar', 'Pawse reads free time only, never event titles.', [['sim', 'demo calendar'], ['sim', 'vet replies']])).catch(() => {});
  await call('vet');
  await hold(2500);
  await tap(next); // Next: call the insurer

  // 7. Insurer call
  await stage('Then the insurer', 'Accident covered, home visit and physio not. Cited from the real AVB terms.', [['live', 'Gradium German voice'], ['sim', 'insurer replies']]);
  await call('insurer');
  await hold(3000);
  await tap(next); // Next: see your options

  // 8. Clinic or home visit
  await app.locator('[data-beat=options]').waitFor({ timeout: 20000 });
  await stage('Clinic about CHF 385 instead of 510', 'The home-visit fee is not covered. The owner chooses.', [['sim', 'demo estimates']]);
  await hold(3500);
  await tap(app.locator('[data-beat=option-clinic]'));
  await hold(1200);
  await tap(app.locator('[data-beat=confirm-call]'));

  // 9. Confirm with the vet
  await stage('Pawse confirms 16:30 with the vet', 'Itemised invoice please, and no physio without asking: it isn’t covered.', [['live', 'Gradium German voice'], ['sim', 'vet reply']]);
  await call('confirm');
  await hold(2000);
  await tap(next); // Next: call a taxi

  // 10. Taxi
  await stage('A taxi that takes cats', '16:05 pickup, cat in a carrier. Transport is not insured.', [['live', 'Gradium German voice'], ['sim', 'taxi reply']]);
  await call('taxi');
  await hold(2000);
  await tap(next); // See your plan

  // 11. Plan
  await app.locator('[data-beat=today]').waitFor({ timeout: 20000 });
  await stage('One plan the owner can act on', '16:05 taxi, 16:30 vet, case summary and claim checklist.', [['live', 'Gemini'], ['live', 'Gradium'], ['sim', 'calls and bookings']]);
  await hold(3000);
  await scrollPhone(900, 20);
  await hold(3500);
  await stage('Pawse', 'A little cat. A helping hand.');
  await hold(3500);
} catch (e) {
  log('FAILED', e.message.split('\n')[0]);
  await page.screenshot({ path: OUT.replace(/\.\w+$/, '-fail.png') });
  process.exitCode = 1;
} finally {
  ff.stdin.write('q');
  await new Promise((r) => ff.on('close', r));
  writeFileSync(OUT.replace(/\.\w+$/, '-marks.json'), JSON.stringify(marks, null, 2));
  await browser.close();
  log('saved', OUT);
}
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Pawse live demo stage</title>
<style>
  :root { --bg: #2a1620; --ink: #fff4f7; --muted: #e8b9c9; --pink: #e0457b; --live: #2fbf71; --sim: #f0a43a; }
  * { box-sizing: border-box; }
  html, body { margin: 0; height: 100%; background: radial-gradient(1200px 800px at 75% 40%, #4a2335 0%, var(--bg) 70%); color: var(--ink);
    font-family: "Inter", "Segoe UI", system-ui, sans-serif; overflow: hidden; cursor: none; }
  .wrap { display: grid; grid-template-columns: 1fr 520px; gap: 64px; height: 100%; padding: 40px 120px 40px 140px; align-items: center; }
  .brand { font-size: 30px; font-weight: 800; letter-spacing: .02em; color: var(--muted); margin-bottom: 48px; }
  .brand b { color: var(--ink); }
  .clock { font-variant-numeric: tabular-nums; color: var(--muted); font-size: 22px; margin-bottom: 18px; }
  .caption { font-size: 64px; line-height: 1.12; font-weight: 800; min-height: 220px; transition: opacity .35s; }
  .sub { font-size: 30px; line-height: 1.35; color: var(--muted); margin-top: 24px; min-height: 90px; transition: opacity .35s; }
  .badges { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 48px; min-height: 60px; }
  .badge { font-size: 22px; font-weight: 700; padding: 10px 18px; border-radius: 999px; border: 2px solid; }
  .badge.live { color: var(--live); border-color: var(--live); }
  .badge.sim { color: var(--sim); border-color: var(--sim); }
  .phone { width: 470px; height: 940px; border-radius: 56px; background: #111; padding: 20px; box-shadow: 0 40px 120px rgba(0,0,0,.55), 0 0 0 2px #333; }
  iframe { width: 430px; height: 900px; border: 0; border-radius: 38px; background: #fff; }
  .badge.gen { color: #8fb8ff; border-color: #8fb8ff; }
  .fade { opacity: 0; }
  #intro { position: fixed; inset: 0; background: #000; z-index: 10; transition: opacity .6s; }
  #intro video { width: 100%; height: 100%; object-fit: cover; }
  #intro .cap { position: absolute; left: 0; right: 0; bottom: 120px; text-align: center; font-size: 60px; font-weight: 800; text-shadow: 0 3px 18px rgba(0,0,0,.8); }
  #intro .tag { position: absolute; top: 40px; right: 48px; font-size: 24px; font-weight: 700; padding: 8px 16px; border-radius: 999px; background: rgba(0,0,0,.5); color: #cfe0ff; }
</style>
</head>
<body>
<div id="intro" hidden><video id="introVideo" muted playsinline></video><div class="cap" id="introCap"></div><div class="tag">AI-generated footage (Gemini)</div></div>
<div class="wrap">
  <section>
    <div class="brand"><b>Pawse</b> · calls the vet in German for you</div>
    <div class="clock" id="clock">Recorded live in the real app</div>
    <div class="caption" id="caption"></div>
    <div class="sub" id="sub"></div>
    <div class="badges" id="badges"></div>
  </section>
  <div class="phone"><iframe id="app" allow="microphone; camera; geolocation; autoplay"></iframe></div>
</div>
<script>
  const q = new URLSearchParams(location.search);
  document.getElementById('app').src = q.get('app') || 'http://127.0.0.1:8790/app/?live=1';
  // Driven by the recorder: window.stage({ caption, sub, badges: [['live', 'Gemini Live'], ['sim', '...']] })
  window.stage = ({ caption = '', sub = '', badges = [] } = {}) => {
    const c = document.getElementById('caption'), s = document.getElementById('sub'), b = document.getElementById('badges');
    c.classList.add('fade'); s.classList.add('fade');
    setTimeout(() => {
      c.textContent = caption; s.textContent = sub;
      b.innerHTML = '';
      for (const [kind, text] of badges) {
        const el = document.createElement('span');
        el.className = `badge ${kind}`;
        el.textContent = ({ live: '● LIVE · ', sim: '◆ SIMULATED · ', gen: '▲ AI-GENERATED · ' })[kind] + text;
        b.appendChild(el);
      }
      c.classList.remove('fade'); s.classList.remove('fade');
    }, 350);
  };
  // Opening shot: plays the (AI-generated) clip full screen with a caption, resolves when it ends.
  // volume: the clip's own sound (lower it under a narrator); keep seconds under the clip's length.
  window.intro = ({ src, caption = '', seconds = 7, volume = 0.6 }) => new Promise((done) => {
    const box = document.getElementById('intro'), v = document.getElementById('introVideo');
    document.getElementById('introCap').textContent = caption;
    v.src = src; v.muted = false; v.volume = volume; v.loop = false; box.hidden = false;
    v.play().catch(() => { v.muted = true; v.play(); });
    setTimeout(() => { box.style.opacity = '0'; setTimeout(() => { box.hidden = true; v.pause(); done(); }, 600); }, seconds * 1000);
