const [error, setError] = useState('');
const [sheetOpen, setSheetOpen] = useState(true);
const [secs, setSecs] = useState(0);
const [caps, setCaps] = useState(null);
const [browser, setBrowser] = useState(() => resolveVoiceName(lang));

const videoRef = useRef(null);
const fileRef = useRef(null);
const agentRef = useRef(null);
const photoUrls = useRef([]);
const onTriageRef = useRef(onTriage);
onTriageRef.current = onTriage;

const mic = useUserMedia({ enabled: wantsAudio && consent && micOn, audio: true });
const cam = useUserMedia({ enabled: camOn, video: true, facing });
// Recording = the mic is open and the agent is taking it in. The meter shows the owner it hears them.
const recording = wantsAudio && micOn && !!mic.stream && listening;
const level = useMicLevel(recording ? mic.stream : null);
const hearing = recording && level >= 0.15;

// ---- the conversation with Pawse
useEffect(() => {
  if (IS_LIVE_VOICE && !consent) return;
  setFellBack(false);
  const agent = createVoiceAgent({ lang, shareWithGemini: consent, voice: gradiumVoice ? { engine: 'gradium', voiceId: gradiumVoice } : null });
  agentRef.current = agent;
  const off = agent.on((e) => {
    switch (e.type) {
      case 'transcript':
        if (e.role === 'ai') setAiLine(e.text);
        else {
          setUserLine(e.text);
          setUserPartial(!!e.partial);
        }
        break;
      case 'transcribing':
        setTranscribing(e.on);
        break;
      case 'speaking':
        setSpeaking(e.who);
        break;
      case 'listening':
        setListening(e.on);
        break;
      case 'suggestions':
        setChips(e.items || []);
        break;
      case 'image_received':
        setPhotos((p) => p.map((x, i) => (i === p.length - 1 ? { ...x, received: true } : x)));
        break;
      case 'tool_result': setToolResults(p => [...p.slice(-4), e]); break;
      case 'agents': setTrace(e.trace); break;
      case 'triage': {
        const problems = validateTriage(e);
        if (problems.length) console.warn('[Pawse] triage violates the contract:', problems, e);
        onTriageRef.current(e);
        setSheetOpen(true);
        break;
      }
      case 'fallback':
        setFellBack(true);
        break;
      case 'error':
        setError(e.message || '');
        break;
      default:
        break;
    }
  });
  agent.setMicMuted(!micOn);
  agent.setOutputMuted?.(!soundOn);
  agent.start();
  return () => {
    off();
    agent.end();
  };
